double vsopComponent(int planet, int var, double T) {
  double sum = 0.0;
  double tp = 1.0;
  const int base = (planet * 3 + var) * 6;
  for (int power = 0; power < 6; ++power) {
    const int off = kVsopIndex[base + power][0];
    const int n = kVsopIndex[base + power][1];
    double s = 0.0;
    for (int i = 0; i < n; ++i) {
      const VsopTerm& t = kVsop[off + i];
      s += t.a * std::cos(t.b + t.c * T);
    }
    sum += s * tp;
    tp *= T;
  }
  return sum;
}
